    if base < 0 {
        return Err("base XP must be nonnegative".into());
    }
    let mut outcomes = vec![];
    for item in items {
        let content = s.reference(*item, "task-item/content")?;
        if s.is_ordinary_question(content)? {
            outcomes.push(
