pub fn compare_math_in_context(
    a: &str,
    b: &str,
    prompt: &str,
    context: symbolic::Context,
) -> Result<bool> {
    if requires_answer_form(prompt) {
        Ok(normalize_answer_form(a) == normalize_answer_form(b))
    } else {
        compare_math(a, b, context)
    }
}

